import json
H=W=30
G=[[0]*W for _ in range(H)]
# Tile frames are 5x5, spaced every 7 cells, with 2-cell zero gutters.
starts=[1,8,15,22,29]
for rs in starts:
  for cs in starts:
    for dr in range(5):
      for dc in range(5):
        r,c=rs+dr,cs+dc
        if r<H and c<W and (dr in (0,4) or dc in (0,4)):
          G[r][c]=4
# Interior 3x3 tile centers; marker matrix from test.
R=[2,9,16,23]; C=[2,9,16,23]
marker=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for i,rr in enumerate(R):
  for j,cc in enumerate(C):
    for dr in range(3):
      for dc in range(3): G[rr+dr][cc+dc]=marker[i][j]
# Extend each rare marker color horizontally/vertically between aligned occurrences,
# painting only zero cells and preserving tile frames and intervening markers.
for color in (3,8):
  # patch centers are 3x3; row/col-aligned equal-color endpoints.
  patches=[(R[i],C[j]) for i in range(4) for j in range(4) if marker[i][j]==color]
  for i,(r1,c1) in enumerate(patches):
    for r2,c2 in patches[i+1:]:
      if r1==r2 and c2>c1:
        for r in range(r1,r1+3):
          for c in range(c1+3,c2):
            if G[r][c]==0: G[r][c]=color
      elif c1==c2 and r2>r1:
        for c in range(c1,c1+3):
          for r in range(r1+3,r2):
            if G[r][c]==0: G[r][c]=color
assert len(G)==30 and all(len(row)==30 for row in G)
assert all(type(x)==int and 0<=x<=9 for row in G for x in row)
# Validate expected examples of connector support.
print('dimensions',len(G),set(map(len,G)))
print('changed connectors',sum(x in (3,8) for row in G for x in row)-sum(x in (3,8) for row in G for x in row))
print(json.dumps({'action':'submit','grid':G},separators=(',',':')))

import json
N=30
src=[[0]*N for _ in range(N)]
starts=[1,8,15,22,29]
# Reconstruct tile borders as observed.
for rs in starts:
 for cs in starts:
  for dr in range(5):
   for dc in range(5):
    r,c=rs+dr,cs+dc
    if r<N and c<N and (dr in (0,4) or dc in (0,4)): src[r][c]=4
R=[2,9,16,23]; C=[2,9,16,23]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for i,r in enumerate(R):
 for j,c in enumerate(C):
  for dr in range(3):
   for dc in range(3): src[r+dr][c+dc]=colors[i][j]
out=[row[:] for row in src]
for color in (3,8):
 patches=[(R[i],C[j]) for i in range(4) for j in range(4) if colors[i][j]==color]
 for k,(r1,c1) in enumerate(patches):
  for r2,c2 in patches[k+1:]:
   if r1==r2 and c2>c1:
    for r in range(r1,r1+3):
     for c in range(c1+3,c2):
      if out[r][c]==0: out[r][c]=color
   elif c1==c2 and r2>r1:
    for c in range(c1,c1+3):
     for r in range(r1+3,r2):
      if out[r][c]==0: out[r][c]=color
assert len(out)==30 and all(len(row)==30 for row in out)
assert set(v for row in out for v in row)<=set(range(10))
delta=[(r,c,src[r][c],out[r][c]) for r in range(N) for c in range(N) if src[r][c]!=out[r][c]]
assert all(old==0 and new in (3,8) for _,_,old,new in delta)
print('validated dimensions=30x30, changed cells=',len(delta),'colors=',sorted(set(new for _,_,_,new in delta)))
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))

